import { createClientFromRequest } from 'npm:@base44/sdk@0.8.6';
import { ethers } from 'npm:ethers@6.10.0';

// Enhanced ERC-20 with Role-Based Access Control
const TOKEN_RBAC_ABI = [
    "constructor(string name, string symbol, uint256 initialSupply, address admin)",
    "function mint(address to, uint256 amount) public",
    "function burn(address from, uint256 amount) public",
    "function transfer(address to, uint256 amount) public returns (bool)",
    "function balanceOf(address account) public view returns (uint256)",
    "function grantRole(bytes32 role, address account) public",
    "function revokeRole(bytes32 role, address account) public",
    "function hasRole(bytes32 role, address account) public view returns (bool)",
    "function MINTER_ROLE() public view returns (bytes32)",
    "function BURNER_ROLE() public view returns (bytes32)",
    "function ADMIN_ROLE() public view returns (bytes32)"
];

// Simplified bytecode - in production, compile from Solidity with AccessControl
const TOKEN_RBAC_BYTECODE = "";

Deno.serve(async (req) => {
    try {
        const base44 = createClientFromRequest(req);
        const user = await base44.auth.me();
        
        if (!user) {
            return Response.json({ error: 'Unauthorized' }, { status: 401 });
        }

        const { program_id, token_name, token_symbol, initial_supply, admin_address } = await req.json();

        if (!program_id || !token_name || !token_symbol) {
            return Response.json({ error: 'Missing required fields' }, { status: 400 });
        }

        // Get program details
        const programs = await base44.asServiceRole.entities.LoyaltyProgram.filter({ id: program_id });
        if (!programs || programs.length === 0) {
            return Response.json({ error: 'Program not found' }, { status: 404 });
        }
        const program = programs[0];

        // Get customer's blockchain config
        const customers = await base44.asServiceRole.entities.LoyaltyCustomer.filter({ 
            admin_email: program.admin_email 
        });
        if (!customers || customers.length === 0) {
            return Response.json({ error: 'Customer not found' }, { status: 404 });
        }

        const configs = await base44.asServiceRole.entities.BlockchainConfig.filter({ 
            customer_id: customers[0].id 
        });
        
        if (!configs || configs.length === 0 || configs[0].provisioning_status !== 'active') {
            return Response.json({ 
                error: 'Blockchain not provisioned for this customer',
                hint: 'Call provisionCustomerBlockchain first'
            }, { status: 400 });
        }

        const blockchainConfig = configs[0];

        // Connect to customer's private chain
        const provider = new ethers.JsonRpcProvider(blockchainConfig.rpc_url);
        const wallet = new ethers.Wallet(blockchainConfig.deployer_private_key, provider);

        // Deploy token contract with RBAC
        const factory = new ethers.ContractFactory(TOKEN_RBAC_ABI, TOKEN_RBAC_BYTECODE, wallet);
        const supply = ethers.parseEther((initial_supply || 1000000).toString());
        const adminAddr = admin_address || wallet.address;
        
        console.log(`Deploying RBAC token: ${token_name} (${token_symbol}) on chain ${blockchainConfig.chain_id}`);
        const contract = await factory.deploy(token_name, token_symbol, supply, adminAddr);
        await contract.waitForDeployment();
        
        const contractAddress = await contract.getAddress();
        console.log(`RBAC Token deployed at: ${contractAddress}`);

        // Update LoyaltyToken entity
        const tokenData = {
            program_id,
            token_name,
            token_symbol,
            blockchain_network: 'polygon_edge',
            contract_address: contractAddress,
            total_supply: initial_supply || 1000000,
            circulating_supply: 0,
            is_blockchain_enabled: true,
            conversion_rate_to_usd: 0.01
        };

        const token = await base44.asServiceRole.entities.LoyaltyToken.create(tokenData);

        // Update program with contract address
        await base44.asServiceRole.entities.LoyaltyProgram.update(program_id, {
            contract_address: contractAddress,
            blockchain_network: 'polygon_edge',
            status: 'active'
        });

        return Response.json({
            success: true,
            token_id: token.id,
            contract_address: contractAddress,
            chain_id: blockchainConfig.chain_id,
            rpc_url: blockchainConfig.rpc_url,
            explorer_url: `${blockchainConfig.explorer_url}/address/${contractAddress}`,
            relay_address: blockchainConfig.relay_address,
            features: {
                gas_free: true,
                role_based_access: true,
                permissioned: true,
                isolated_chain: true
            }
        });

    } catch (error) {
        console.error('RBAC token deployment error:', error);
        return Response.json({ error: error.message }, { status: 500 });
    }
});